// @vitest-environment node
// No raw colours (docs/design.md: "Never write a hex value in a component").
// Every file under app/, components/ and lib/ uses the tokens of
// styles/tokens.css instead. components/vendor/ and components/ui/ hold code
// generated by the shadcn CLI and are not checked.
//
// The check is strict: "#123" in a comment also counts as a hex colour, so
// write an issue or PR reference as "issue 123" in these folders.
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { describe, expect, it } from "vitest";

const root = fileURLToPath(new URL("..", import.meta.url));
const scanned = ["app", "components", "lib"];
const skipped = ["components/vendor", "components/ui"];
const textFile = /\.(?:[cm]?[jt]sx?|css|scss|json|mdx?|svg|html)$/;

/** A hex colour: # and 3, 4, 6 or 8 hex digits, not followed by another word character. */
const HEX_COLOUR = /#(?:[0-9a-f]{8}|[0-9a-f]{6}|[0-9a-f]{3,4})(?![\w-])/gi;

function filesUnder(dir: string): string[] {
  const rel = path.relative(root, dir).split(path.sep).join("/");
  if (skipped.includes(rel) || !fs.existsSync(dir)) return [];
  return fs.readdirSync(dir, { withFileTypes: true }).flatMap((entry) => {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) return filesUnder(full);
    return textFile.test(entry.name) ? [full] : [];
  });
}

describe("no raw hex colours", () => {
  it("finds hex colours and leaves ids and short numbers alone", () => {
    const find = (text: string) => text.match(HEX_COLOUR) ?? [];
    expect(find('color: "#fff"; background: #15663C; border: #15663c80; x: #abcd')).toEqual([
      "#fff",
      "#15663C",
      "#15663c80",
      "#abcd",
    ]);
    expect(find('href="#main" href="/#how-it-works" id="#faq" #ui-lane Task: #3 #12 #ad-hoc')).toEqual([]);
  });

  it("has none in app/, components/ or lib/ (except components/vendor/ and components/ui/)", () => {
    const files = scanned.flatMap((dir) => filesUnder(path.join(root, dir)));
    expect(files.length).toBeGreaterThan(0);
    const offenders = files.flatMap((file) =>
      fs
        .readFileSync(file, "utf8")
        .split("\n")
        .flatMap((line, i) =>
          (line.match(HEX_COLOUR) ?? []).map(
            (hex) => `${path.relative(root, file).split(path.sep).join("/")}:${i + 1} ${hex}`,
          ),
        ),
    );
    expect(offenders, "use a token from styles/tokens.css instead").toEqual([]);
  });
});
